// BIP-173 reference polymod/checksum functions (checksum constant 1, NOT bech32m).

export function polymod(values) {
  const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];
  let chk = 1;
  for (const v of values) {
    const top = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      if ((top >> i) & 1) {
        chk ^= GEN[i];
      }
    }
  }
  return chk;
}

export function hrpExpand(hrp) {
  return [...hrp].map((c) => c.charCodeAt(0) >> 5)
    .concat([0])
    .concat([...hrp].map((c) => c.charCodeAt(0) & 31));
}

export function verifyChecksum(hrp, data) {
  return polymod(hrpExpand(hrp).concat(data)) === 1;
}

export function createChecksum(hrp, data) {
  const values = hrpExpand(hrp).concat(data, [0, 0, 0, 0, 0, 0]);
  const pm = polymod(values) ^ 1;
  const ret = [];
  for (let i = 0; i < 6; i++) {
    ret.push((pm >> (5 * (5 - i))) & 31);
  }
  return ret;
}

// Low-level bech32 encode/decode, mirroring the Python bech32 reference package.

import { CHARSET } from './charset.mjs';
import { verifyChecksum, createChecksum } from './polymod.mjs';

export function bech32Encode(hrp, data) {
  const combined = data.concat(createChecksum(hrp, data));
  return hrp + '1' + combined.map((d) => CHARSET[((d % 32) + 32) % 32]).join('');
}

export function bech32Decode(bech) {
  // Iterating null/undefined throws a TypeError, mirroring Python iterating None.
  if ([...bech].some((c) => c.charCodeAt(0) < 33 || c.charCodeAt(0) > 126)) {
    return [null, null];
  }
  if (bech.toLowerCase() !== bech && bech.toUpperCase() !== bech) {
    return [null, null];
  }
  bech = bech.toLowerCase();
  const pos = bech.lastIndexOf('1');
  if (pos < 1 || pos + 7 > bech.length) {
    return [null, null];
  }
  if ([...bech.slice(pos + 1)].some((x) => !CHARSET.includes(x))) {
    return [null, null];
  }
  const hrp = bech.slice(0, pos);
  const data = [...bech.slice(pos + 1)].map((x) => CHARSET.indexOf(x));
  if (!verifyChecksum(hrp, data)) {
    return [null, null];
  }
  return [hrp, data.slice(0, data.length - 6)];
}

