import { polymod, hrpExpand, verifyChecksum, createChecksum } from '/tmp/b32test/polymod.mjs';
import { bech32Encode, bech32Decode } from '/tmp/b32test/bech32Core.mjs';

const data = [0,0,4,1,0,6,1,0,5,0,24,3,16,16,2,8,10,1,12,6,0,26,3,16,15,2,0,8,17,4,4,24,20];
const expected = 'bc1qqqzqzqqxqyqq2qqcqvgpqqsgpgqscpsqrgp3qrczqqypzpqyrq2qrmgw7j';

const enc = bech32Encode('bc', data);
console.log('encode ok:', enc === expected, enc);

const [hrp, dec] = bech32Decode(expected);
console.log('decode hrp ok:', hrp === 'bc');
console.log('decode data ok:', JSON.stringify(dec) === JSON.stringify(data));

const pm = polymod(hrpExpand('tb').concat([...'rg0s58shry0sxxqmzcd32zc9qcv3zqsxzg0skrcvq5g3k9gmpcgs8jnqnz'].map(x => CHARSET.indexOf(x))));
console.log('polymod tb ok:', pm === 1);

// extra sanity checks
console.log('decode null throws TypeError:', (() => { try { bech32Decode(null); return false; } catch (e) { return e instanceof TypeError; } })());
console.log('decode bad charset:', JSON.stringify(bech32Decode('bc1' + expected.slice(3, -1) + '!')));
console.log('decode mixed case:', JSON.stringify(bech32Decode('bC1qqqzqzqqxqyqq2qqcqvgpqqsgpgqscpsqrgp3qrczqqypzpqyrq2qrmgw7j')));
console.log('decode no separator:', JSON.stringify(bech32Decode('qqqqqqqq')));
console.log('decode bad checksum:', JSON.stringify(bech32Decode(expected.slice(0, -1) + (expected.endsWith('j') ? 'k' : 'j'))));
console.log('uppercase roundtrip:', JSON.stringify(bech32Decode(expected.toUpperCase()))[0] !== 'n');
console.log('encode negative index:', bech32Encode('a', [-1]) === 'a1l7f3zn');

